<script module lang="ts">
/**
 * A hierarchy opened level by level, with one item picked (`design/components/tree.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/tree.module.css'
import Spinner from './Spinner.svelte'
import TreeNode from './TreeNode.svelte'

export interface TreeItem {
  /** Unique in the tree. `change`, `expandedChange` and `loadMore` report it. */
  id: string
  label: string
  /** One supporting line under the label. */
  description?: string
  /** The items under it. An item with one or more is a branch. */
  children?: TreeItem[]
  /**
   * A branch whose items the app loads when it is first opened. With no `children` the
   * branch opens onto nothing until the app passes them.
   */
  hasChildren?: boolean
  /** The branch's level is loading. An open branch draws one busy row under itself. */
  loading?: boolean
  /** The branch has more items than `children` holds: a last row asks for them. */
  hasMore?: boolean
  /** The item takes no key and no press, the arrow keys pass over it, and a branch stays closed. */
  disabled?: boolean
}

export interface TreeMessages {
  /** What a level says while it loads. */
  loading: string
  /** The row that asks for more of a level. */
  loadMore: string
}

export interface TreeProps {
  /**
   * The branches open at first, while the tree holds the set.
   */
  defaultExpanded?: ReadonlySet<string>
  /**
   * The item selected at first, while the tree holds the selection.
   */
  defaultValue?: string
  /**
   * The open branches by id. Controlled when given; without it the tree holds the set.
   */
  expanded?: ReadonlySet<string>
  /**
   * The top level has more items than `items` holds: a last row asks for them.
   */
  hasMore?: boolean
  /**
   * The top level.
   */
  items: TreeItem[]
  /**
   * Names the tree for a reader: "Organization units", not "Tree".
   */
  label: string
  /**
   * The top level is loading, as an item's `loading` says of its own level.
   */
  loading?: boolean
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: TreeMessages
  /**
   * Called with the id of the item a reader selects.
   */
  onChange?: (id: string) => void
  /**
   * Called with the next set of open branches, controlled or not.
   */
  onExpandedChange?: (next: ReadonlySet<string>) => void
  /**
   * Called with a branch's id, or `null` for the top level, when a reader asks for more.
   */
  onLoadMore?: (parentId: string | null) => void
  /**
   * The selected item's id. Controlled when given, and `null` selects nothing.
   */
  value?: string | null
}
</script>

<script lang="ts">
let {
  defaultExpanded,
  defaultValue,
  expanded,
  hasMore = false,
  items,
  label: labelOwn,
  loading = false,
  messages = (() => ({ loading: 'Loading', loadMore: 'Load more' }))(),
  onChange,
  onExpandedChange,
  onLoadMore,
  value,
}: TreeProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
// svelte-ignore state_referenced_locally
let ownExpanded = $state(defaultExpanded ?? new Set<string>())
// svelte-ignore state_referenced_locally
let ownValue = $state((defaultValue ?? null) as string | null)
let placed = $state(false)
let held = $state(false)
let asked = $state(null as { parent: string | null; count: number } | null)
let moving = $state(false)
let root = $state<HTMLElement | null>(null)
const open = $derived(expanded ?? ownExpanded)
const selected = $derived(value === undefined ? ownValue : value)
const shownItems = $derived(
  (() => {
    const seen: TreeItem[] = []
    const walk = (level: readonly TreeItem[]): void => {
      for (const item of level) {
        seen.push(item)
        if (item.disabled !== true && open.has(item.id)) walk(item.children ?? [])
      }
    }
    walk(items)
    return seen
  })(),
)
const branchOf = $derived((id: string): void => {
  const item = shownItems.find((candidate) => candidate.id === id)
  if ((item?.children?.length ?? 0) === 0 && item?.hasChildren !== true)
    throw new Error(`"${item?.label ?? id}" is not a branch, so it does not open or close.`)
})
const rowsOf = $derived((tree: HTMLElement): HTMLElement[] =>
  Array.from(tree.querySelectorAll<HTMLElement>('[role="treeitem"]:not([aria-disabled="true"])')),
)
const parentOf = $derived(
  (row: Element): string | null =>
    row.parentElement?.closest('[role="treeitem"]')?.getAttribute('data-tree-item') ?? null,
)
const levelOf = $derived((tree: HTMLElement, parent: string | null): Element | null =>
  parent === null
    ? tree
    : (Array.from(tree.querySelectorAll('[role="treeitem"]'))
        .find((row) => row.getAttribute('data-tree-item') === parent)
        ?.querySelector(':scope > [role="group"]') ?? null),
)
const itemsIn = $derived((list: Element): HTMLElement[] =>
  Array.from(list.children).filter(
    (child): child is HTMLElement =>
      child instanceof HTMLElement &&
      child.matches('[role="treeitem"]') &&
      !child.matches('[data-tree-part="more"]'),
  ),
)
const stopOf = $derived((tree: HTMLElement): HTMLElement | null => {
  const rows = rowsOf(tree)
  const now = placed ? rows.find((row) => row.getAttribute('tabindex') === '0') : undefined
  return now ?? rows.find((row) => row.getAttribute('aria-selected') === 'true') ?? rows[0] ?? null
})
const rove = $derived((tree: HTMLElement, stop: HTMLElement | null) => {
  for (const row of Array.from(tree.querySelectorAll<HTMLElement>('[role="treeitem"]'))) {
    if (row !== stop && row.getAttribute('aria-disabled') === 'true') {
      row.removeAttribute('tabindex')
      continue
    }
    const wanted = row === stop ? '0' : '-1'
    if (row.getAttribute('tabindex') !== wanted) row.setAttribute('tabindex', wanted)
  }
})
const settle = $derived(() => {
  const tree = root as HTMLElement | null
  if (tree === null) return
  const lost = held && !tree.contains(document.activeElement)
  const request = asked
  let to: HTMLElement | null = null
  if (request !== null) {
    const list = levelOf(tree, request.parent)
    const found = list === null ? [] : itemsIn(list)
    if (list === null) asked = null
    else if (found.length > request.count) {
      if (held)
        to =
          found
            .slice(request.count)
            .find((row) => row.matches('[role="treeitem"]:not([aria-disabled="true"])')) ??
          stopOf(tree)
      asked = null
    }
  }
  if (to === null && lost) to = stopOf(tree)
  if (to === null) {
    rove(tree, stopOf(tree))
    return
  }
  rove(tree, to)
  moving = true
  to.focus()
  moving = false
})
const ask = $derived((row: HTMLElement) => {
  const list = row.parentElement
  if (list === null || row.getAttribute('aria-busy') === 'true') return
  const parent = parentOf(row)
  asked = { parent, count: itemsIn(list).length }
  onLoadMore?.(parent)
})
const toggle = $derived((id: string) => {
  const next = new Set(open)
  if (next.has(id)) next.delete(id)
  else next.add(id)
  ownExpanded = next
  onExpandedChange?.(next)
})
const choose = $derived((id: string) => {
  if (id === selected) return
  ownValue = id
  onChange?.(id)
})
const focusIn = $derived((event: FocusEvent) => {
  const tree = root as HTMLElement | null
  const row =
    event.target instanceof Element ? event.target.closest<HTMLElement>('[role="treeitem"]') : null
  if (tree === null || row === null) return
  held = true
  placed = true
  const request = asked
  if (
    !moving &&
    !(
      request !== null &&
      row.matches('[data-tree-part="more"]') &&
      parentOf(row) === request.parent
    )
  )
    asked = null
  rove(tree, row)
})
const focusOut = $derived((event: FocusEvent) => {
  const tree = root as HTMLElement | null
  const row = event.target
  queueMicrotask(() => {
    if (tree === null || !(row instanceof Element) || !row.isConnected) return
    if (!tree.contains(document.activeElement)) held = false
  })
})
const keyDown = $derived((event: KeyboardEvent) => {
  const tree = root as HTMLElement | null
  const here =
    event.target instanceof Element ? event.target.closest<HTMLElement>('[role="treeitem"]') : null
  if (tree === null || here === null || event.altKey || event.ctrlKey || event.metaKey) return
  const rows = rowsOf(tree)
  const at = rows.indexOf(here)
  const rtl = getComputedStyle(tree).direction === 'rtl'
  const inward = rtl ? 'ArrowLeft' : 'ArrowRight'
  const outward = rtl ? 'ArrowRight' : 'ArrowLeft'
  const id = here.matches('[role="treeitem"]:not([aria-disabled="true"])')
    ? here.getAttribute('data-tree-item')
    : null
  const state = here.getAttribute('aria-expanded')
  let to: HTMLElement | null | undefined = null
  switch (event.key) {
    case 'ArrowDown':
      to = rows[at + 1]
      break
    case 'ArrowUp':
      to = at > 0 ? rows[at - 1] : null
      break
    case 'Home':
      to = rows[0]
      break
    case 'End':
      to = rows[rows.length - 1]
      break
    case inward:
      if (id !== null && state === 'false') toggle(id)
      else if (state === 'true')
        to = here.querySelector<HTMLElement>(
          ':scope > [role="group"] > [role="treeitem"]:not([aria-disabled="true"])',
        )
      break
    case outward:
      if (id !== null && state === 'true') toggle(id)
      else
        to = here.parentElement?.closest<HTMLElement>(
          '[role="treeitem"]:not([aria-disabled="true"])',
        )
      break
    case 'Enter':
    case ' ':
      if (here.matches('[data-tree-part="more"]')) ask(here)
      else if (id !== null) choose(id)
      break
    default:
      return
  }
  event.preventDefault()
  if (to === null || to === undefined) return
  rove(tree, to)
  to.focus()
})
const press = $derived((event: MouseEvent) => {
  const target = event.target instanceof Element ? event.target : null
  const row = target?.closest('[data-tree-part="row"]')?.parentElement ?? null
  if (
    target === null ||
    row === null ||
    !row.matches('[role="treeitem"]:not([aria-disabled="true"])')
  )
    return
  const id = row.getAttribute('data-tree-item')
  if (row.matches('[data-tree-part="more"]')) ask(row)
  else if (id === null) return
  else if (target.closest('[data-tree-part="toggle"]') !== null) toggle(id)
  else choose(id)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    settle()
  }
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [root])
    if (element)
      mutation?.observe(element, {
        childList: true,
        characterData: true,
        subtree: true,
        attributeFilter: ['aria-selected', 'aria-disabled'],
      })
  release1 = () => {
    mutation?.disconnect()
  }
  run()
}
watchEffect(effect1)
onDestroy(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Tree',
    element: () => root,
    state: () => ({
      value: selected ?? null,
      expanded: [...open],
      items: shownItems.map((item) => ({
        id: item.id,
        label: item.label,
        ...(item.disabled === true ? { disabled: true } : {}),
      })),
      loading: loading,
    }),
    actions: {
      choose: { argument: 'id', run: (value) => choose(value) },
      expand: {
        argument: 'id',
        run: (value) => (branchOf(value), open.has(value) || toggle(value)),
      },
      collapse: {
        argument: 'id',
        run: (value) => (branchOf(value), open.has(value) && toggle(value)),
      },
    },
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<ul
    bind:this={root}
    class={styles.root}
    role="tree"
    aria-label={label}
    aria-busy={(loading) ? true : undefined}
    data-member="tree"
    onfocusin={(event) => { focusIn(event) }}
    onfocusout={(event) => { focusOut(event) }}
    onkeydown={(event) => { keyDown(event) }}
    onclick={(event) => { press(event) }}
    >{#each items as child (child.id)
      }<TreeNode item={child} level={0} {open} {selected} {messages}
    />{/each
    }{#if hasMore
      }<li
        class={styles.item}
        role="treeitem"
        aria-labelledby={`${uid}-more`}
        aria-selected="false"
        aria-busy={(loading) ? true : undefined}
        data-tree-part="more"
        ><div
          class={styles.row}
          style:--pm-tree-level={0}
          data-tree-part="row"
          data-busy={(loading) ? '' : undefined}
          ><span class={styles.slot}
            >{#if loading}<Spinner size="sm" label={messages.loading} />{/if
          }</span
          ><span class={styles.text}
            ><span class={styles.more} id={`${uid}-more`}
              >{(loading) ? messages.loading : messages.loadMore
            }</span
          ></span
        ></div
      ></li
    >{:else if loading
      }<li class={styles.item} role="none"
        ><div class={styles.row} style:--pm-tree-level={0} data-busy=""
          ><span class={styles.slot}><Spinner size="sm" label={messages.loading} /></span
          ><span class={styles.text}
            ><span class={styles.status} aria-hidden="true">{messages.loading}</span
          ></span
        ></div
      ></li
    >{/if
  }</ul
>{/if
}{@render joined.end?.()}
